import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';

/**
 * CSS regression test for issue #1063 — dashicon alignment inside Imagify buttons.
 *
 * WordPress 7.0 introduced:
 *   .wp-core-ui .button .dashicons { line-height: 1.9; vertical-align: top; }
 *
 * The fix in admin.css adds `line-height: 1` to two Imagify-scoped selectors so
 * dashicons stay vertically centred with their label text.
 *
 * These tests verify:
 * 1. The computed `line-height` on dashicon elements inside Imagify buttons is "1"
 *    (i.e. the WP 7.0 override is neutralised).
 * 2. The computed `vertical-align` is "middle".
 * 3. Both selector groups are covered:
 *    a) `[class*="imagify-"] .button .dashicons`
 *    b) `.imagify-button-primary .dashicons` / `.imagify-button-secondary .dashicons`
 */
test.describe( 'Dashicon alignment inside Imagify buttons (issue #1063)', () => {
	test.beforeEach( async ( { page } ) => {
		await loginAsAdmin( page );
	} );

	test( 'Settings page: dashicons inside .button elements have line-height 1 and vertical-align middle', async ( { page } ) => {
		await page.goto( '/wp-admin/options-general.php?page=imagify' );
		await page.waitForLoadState( 'networkidle' );

		// The Settings page lives inside a wrapper that contains "imagify" in its class,
		// so [class*="imagify-"] selector applies.
		// Find the first dashicon inside any .button inside an imagify-prefixed wrapper.
		const dashicon = page.locator( '[class*="imagify-"] .button .dashicons' ).first();

		// If there are no dashicons on this page without an API key, the test is
		// informational — we check the CSS property via evaluate instead.
		const count = await dashicon.count();
		if ( count === 0 ) {
			// Inject a synthetic button to verify the CSS rules are loaded.
			const lineHeight = await page.evaluate( () => {
				const wrapper = document.createElement( 'div' );
				wrapper.className = 'imagify-settings';
				const btn = document.createElement( 'button' );
				btn.className = 'button';
				const icon = document.createElement( 'span' );
				icon.className = 'dashicons dashicons-update';
				btn.appendChild( icon );
				wrapper.appendChild( btn );
				document.body.appendChild( wrapper );
				const style = window.getComputedStyle( icon );
				const result = {
					lineHeight: style.lineHeight,
					verticalAlign: style.verticalAlign,
				};
				document.body.removeChild( wrapper );
				return result;
			} );

			// line-height: 1 on a typical 13px body = "13px", but the value depends
			// on the browser's font-size. We check it is NOT "1.9 * font-size".
			const fontSize = await page.evaluate( () => parseFloat( window.getComputedStyle( document.body ).fontSize ) );
			const computedLH = parseFloat( lineHeight.lineHeight );
			// With line-height: 1, computedLH should equal fontSize (± 1px).
			// With line-height: 1.9, it would be ~1.9× larger.
			expect( computedLH ).toBeLessThanOrEqual( fontSize * 1.1 );
			expect( lineHeight.verticalAlign ).toBe( 'middle' );
			return;
		}

		// Happy path: a real dashicon exists in the DOM.
		const lineHeight = await dashicon.evaluate( ( el ) => window.getComputedStyle( el ).lineHeight );
		const verticalAlign = await dashicon.evaluate( ( el ) => window.getComputedStyle( el ).verticalAlign );

		const fontSize = await page.evaluate( () => parseFloat( window.getComputedStyle( document.body ).fontSize ) );
		const computedLH = parseFloat( lineHeight );

		// line-height: 1 → computed value equals font-size (± 1px rounding).
		expect( computedLH ).toBeLessThanOrEqual( fontSize * 1.1 );
		expect( verticalAlign ).toBe( 'middle' );
	} );

	test( 'Settings page: .imagify-button-primary .dashicons have line-height 1 and vertical-align middle', async ( { page } ) => {
		await page.goto( '/wp-admin/options-general.php?page=imagify' );
		await page.waitForLoadState( 'networkidle' );

		// Inject a synthetic .imagify-button-primary element with a dashicon child
		// to verify that the second selector group in the fix also applies.
		const result = await page.evaluate( () => {
			const btn = document.createElement( 'button' );
			btn.className = 'imagify-button-primary imagify-button-primary button';
			const icon = document.createElement( 'span' );
			icon.className = 'dashicons dashicons-update';
			btn.appendChild( icon );
			document.body.appendChild( btn );
			const style = window.getComputedStyle( icon );
			const data = {
				lineHeight: style.lineHeight,
				verticalAlign: style.verticalAlign,
				fontSize: parseFloat( window.getComputedStyle( document.body ).fontSize ),
			};
			document.body.removeChild( btn );
			return data;
		} );

		const computedLH = parseFloat( result.lineHeight );
		// line-height: 1 → computed value equals font-size (± 10 % rounding tolerance).
		expect( computedLH ).toBeLessThanOrEqual( result.fontSize * 1.1 );
		expect( result.verticalAlign ).toBe( 'middle' );
	} );

	test( 'Bulk Optimization page: dashicons inside imagify-prefixed buttons have line-height 1', async ( { page } ) => {
		await page.goto( '/wp-admin/upload.php?page=imagify-bulk-optimization' );
		await page.waitForLoadState( 'networkidle' );

		// Check via CSS eval — same synthetic-element technique for reliability.
		const result = await page.evaluate( () => {
			// Find a real dashicon if present.
			const real = document.querySelector<HTMLElement>( '[class*="imagify-"] .button .dashicons' );
			const target = real ?? ( () => {
				const wrapper = document.createElement( 'div' );
				wrapper.className = 'imagify-bulk';
				const btn = document.createElement( 'button' );
				btn.className = 'button';
				const icon = document.createElement( 'span' );
				icon.className = 'dashicons dashicons-update';
				btn.appendChild( icon );
				wrapper.appendChild( btn );
				document.body.appendChild( wrapper );
				return icon;
			} )();

			const style = window.getComputedStyle( target );
			const data = {
				lineHeight: style.lineHeight,
				verticalAlign: style.verticalAlign,
				fontSize: parseFloat( window.getComputedStyle( document.body ).fontSize ),
				synthetic: ! real,
			};

			if ( data.synthetic ) {
				// Clean up the synthetic element.
				target.closest( '.imagify-bulk' )?.remove();
			}
			return data;
		} );

		const computedLH = parseFloat( result.lineHeight );
		expect( computedLH ).toBeLessThanOrEqual( result.fontSize * 1.1 );
		expect( result.verticalAlign ).toBe( 'middle' );
	} );

	test( 'Settings page screenshot — button icon alignment visual check', async ( { page } ) => {
		await page.goto( '/wp-admin/options-general.php?page=imagify' );
		await page.waitForLoadState( 'networkidle' );

		// Take a full-page screenshot for visual inspection of button alignment.
		await page.screenshot( {
			path: '.e2e-screenshots/settings-button-alignment.png',
			fullPage: false,
		} );

		// No assertion — this is a visual reference. The test passes as long as
		// the page loads without errors.
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );

	test( 'Bulk Optimization page screenshot — button icon alignment visual check', async ( { page } ) => {
		await page.goto( '/wp-admin/upload.php?page=imagify-bulk-optimization' );
		await page.waitForLoadState( 'networkidle' );

